{
  "name": "@nevermore93/opencode-worktree",
  "version": "0.5.3",
  "description": "OpenCode plugin for multi-repo workspace worktree orchestration",
  "type": "module",
  "main": "dist/plugin/worktree.js",
  "types": "dist/plugin/worktree.d.ts",
  "exports": {
    ".": {
      "types": "./dist/plugin/worktree.d.ts",
      "default": "./dist/plugin/worktree.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "prepublishOnly": "bun run build && bun run typecheck",
    "release": "bumpp"
  },
  "author": "NeverMore93",
  "repository": {
    "type": "git",
    "url": "https://github.com/NeverMore93/opencode-worktree"
  },
  "homepage": "https://github.com/NeverMore93/opencode-worktree#readme",
  "dependencies": {
    "jsonc-parser": "^3.3.1",
    "zod": "^3.24.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.1.0",
    "@opencode-ai/sdk": ">=1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.14.18",
    "@opencode-ai/sdk": "^1.0.0",
    "@types/bun": "^1.2.0",
    "bumpp": "^10.4.1",
    "tsup": "^8.5.1",
    "typescript": "^5.5.0"
  },
  "engines": {
    "node": ">=20.3.0",
    "bun": ">=1.0.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "worktree",
    "workspace",
    "git",
    "multi-repo"
  ],
  "license": "MIT"
}
